const mockComments = [
  {
    id: 1,
    fba_location_id: 'ABE2',
    user_id: 1,
    parent_id: null,
    content: '这个仓库处理速度很快，通常在24小时内就能处理完入库。推荐！',
    created_at: '2024-01-15T10:30:00Z',
    is_deleted: false,
    user: {
      id: 1,
      first_name: 'John',
      last_name: 'Smith',
      email: 'john@example.com'
    },
    mediaFiles: [],
    like_count: 5,
    is_liked: false,
    replies: []
  },
  {
    id: 2,
    fba_location_id: 'ABE2',
    user_id: 2,
    parent_id: null,
    content: '位置很方便，离高速公路很近。不过有时候排队时间比较长。',
    created_at: '2024-01-10T14:20:00Z',
    is_deleted: false,
    user: {
      id: 2,
      first_name: 'Sarah',
      last_name: 'Johnson',
      email: 'sarah@example.com'
    },
    mediaFiles: [],
    like_count: 3,
    is_liked: false,
    replies: []
  }
];

// 动态数据存储
let commentStorage = [...mockComments];
let commentLikes = [];
let nextCommentId = 4;
let nextLikeId = 1;

// 获取所有FBA位置
router.get('/locations', optionalAuth, (req, res) => {
  try {
    res.json({
      success: true,
      data: mockLocations,
      pagination: {
        page: 1,
        limit: 20,
        total: mockLocations.length,
        pages: 1
      }
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      message: '获取FBA位置列表失败',
      error: error.message
    });
  }
});

// 获取单个FBA位置详情
router.get('/locations/:code', optionalAuth, (req, res) => {
  try {
    const { code } = req.params;
    const location = mockLocations.find(loc => loc.code === code);

    if (!location) {
      return res.status(404).json({
        success: false,
        message: 'FBA位置不存在'
      });
    }

    res.json({
      success: true,
      data: location
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      message: '获取FBA位置详情失败',
      error: error.message
    });
  }
});

// 获取FBA位置的评论列表
router.get('/locations/:code/comments', optionalAuth, (req, res) => {
  try {
    const { code } = req.params;
    const location = mockLocations.find(loc => loc.code === code);

    if (!location) {
      return res.status(404).json({
        success: false,
        message: 'FBA位置不存在'
      });
    }

    // 获取所有父评论
    const parentComments = commentStorage.filter(c => 
      c.fba_location_id === code && 
      !c.is_deleted && 
      !c.parent_id
    );

    // 为每个父评论加载回复
    const commentsWithReplies = parentComments.map(parent => {
      // 查找该父评论的所有回复
      const replies = commentStorage.filter(c => 
        c.fba_location_id === code && 
        !c.is_deleted && 
        c.parent_id === parent.id
      );

      // 为回复添加点赞状态和计数
      const repliesWithLikes = replies.map(reply => {
        const likeCount = commentLikes.filter(l => l.comment_id === reply.id).length;
        const isLiked = req.user ? 
          commentLikes.some(l => l.comment_id === reply.id && l.user_id === req.user.id) : 
          false;

        return {
          ...reply,
          like_count: likeCount,
          is_liked: isLiked
        };
      });

      // 为父评论添加点赞状态、计数和回复
      const likeCount = commentLikes.filter(l => l.comment_id === parent.id).length;
      const isLiked = req.user ? 
        commentLikes.some(l => l.comment_id === parent.id && l.user_id === req.user.id) : 
        false;

      return {
        ...parent,
        like_count: likeCount,
        is_liked: isLiked,
        replies: repliesWithLikes
      };
    });

    res.json({
      success: true,
      data: commentsWithReplies,
      pagination: {
        page: 1,
        limit: 10,
        total: commentsWithReplies.length,
        pages: 1
      }
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      message: '获取评论列表失败',
      error: error.message
    });
  }
});

// 发表评论
router.post('/locations/:code/comments', upload.array('media', 5), auth, (req, res) => {
  try {
    const { code } = req.params;
    const { content, parent_id } = req.body;
    const userId = req.user.id;

    if (!content || content.trim().length === 0) {
      return res.status(400).json({
        success: false,
        message: '评论内容不能为空'
      });
    }

    // 检查位置是否存在
    const location = mockLocations.find(loc => loc.code === code);
    if (!location) {
      return res.status(404).json({
        success: false,
        message: 'FBA位置不存在'
      });
    }

    // 如果是回复，检查父评论
    if (parent_id) {
      const parentComment = commentStorage.find(c => 
        c.id === parseInt(parent_id) && 
        c.fba_location_id === code && 
        !c.is_deleted
      );
      if (!parentComment) {
        return res.status(404).json({
          success: false,
          message: '父评论不存在'
        });
      }
    }

    // 创建新评论
    const newComment = {
      id: nextCommentId++,
      fba_location_id: code,
      user_id: userId,
      parent_id: parent_id ? parseInt(parent_id) : null,
      content: content.trim(),
      created_at: new Date().toISOString(),
      is_deleted: false,
      user: {
        id: userId,
        first_name: req.user.first_name,
        last_name: req.user.last_name,
        email: req.user.email
      },
      mediaFiles: [],
      like_count: 0,
      is_liked: false
    };

    if (!parent_id) {
      newComment.replies = [];
    }

    commentStorage.push(newComment);

    res.status(201).json({
      success: true,
      message: '评论发表成功',
      data: newComment
    });
  } catch (error) {
    console.error('发表评论失败:', error);
    res.status(500).json({
      success: false,
      message: '发表评论失败',
      error: error.message
    });
  }
});

// 点赞/取消点赞评论
router.post('/comments/:commentId/like', auth, (req, res) => {
  try {
    const { commentId } = req.params;
    const userId = req.user.id;

    const comment = commentStorage.find(c => c.id === parseInt(commentId) && !c.is_deleted);
    if (!comment) {
      return res.status(404).json({
        success: false,
        message: '评论不存在'
      });
    }

    const existingLike = commentLikes.find(l => 
      l.comment_id === parseInt(commentId) && l.user_id === userId
    );

    if (existingLike) {
      // 取消点赞
      const index = commentLikes.findIndex(l => l.id === existingLike.id);
      commentLikes.splice(index, 1);

      const likeCount = commentLikes.filter(l => l.comment_id === parseInt(commentId)).length;
      
      res.json({
        success: true,
        message: '取消点赞成功',
        data: {
          is_liked: false,
          like_count: likeCount
        }
      });
    } else {
      // 添加点赞
      commentLikes.push({
        id: nextLikeId++,
        comment_id: parseInt(commentId),
        user_id: userId,
        created_at: new Date().toISOString()
      });

      const likeCount = commentLikes.filter(l => l.comment_id === parseInt(commentId)).length;
      
      res.json({
        success: true,
        message: '点赞成功',
        data: {
          is_liked: true,
          like_count: likeCount
        }
      });
    }
  } catch (error) {
    console.error('点赞操作失败:', error);
    res.status(500).json({
      success: false,
      message: '点赞操作失败',
      error: error.message
    });
  }
});

// 删除评论
router.delete('/comments/:commentId', auth, (req, res) => {
  try {
    const { commentId } = req.params;
    const userId = req.user.id;

    const comment = commentStorage.find(c => 
      c.id === parseInt(commentId) && 
      c.user_id === userId && 
      !c.is_deleted
    );

    if (!comment) {
      return res.status(404).json({
        success: false,
        message: '评论不存在或无权限删除'
      });
    }

    // 软删除
    comment.is_deleted = true;
    comment.deleted_at = new Date().toISOString();

    res.json({
      success: true,
      message: '评论删除成功'
    });
  } catch (error) {
    console.error('删除评论失败:', error);
    res.status(500).json({
      success: false,
      message: '删除评论失败',
      error: error.message
    });
  }
});

module.exports = router;